from collections import defaultdict


def transform(grid):
    h, w = len(grid), len(grid[0])
    nonzero = [(r, c, v) for r, row in enumerate(grid)
               for c, v in enumerate(row) if v != 0]

    # Solid horizontal bars encode a periodic sequence of row colors.
    bars = [(r, row[0]) for r, row in enumerate(grid)
            if row[0] != 0 and all(v == row[0] for v in row)]
    if bars and len(nonzero) == len(bars) * w:
        period = None
        for p in range(1, h + 1):
            phases = {}
            for r, color in bars:
                phase = r % p
                if phase in phases and phases[phase] != color:
                    break
                phases[phase] = color
            else:
                if len(phases) == p:
                    period = p
                    break
        if period is None:
            period = max(r for r, _ in bars) + 1
            phases = {r % period: color for r, color in bars}
        return [[phases[r % period]] * w for r in range(h)]

    # Sparse marks encode an anti-diagonal periodic color sequence.
    for period in range(2, min(15, h + w) + 1):
        groups = defaultdict(set)
        for r, c, color in nonzero:
            groups[(r + c) % period].add(color)
        if len(groups) == period and all(len(colors) == 1 for colors in groups.values()):
            phase_color = {phase: next(iter(colors)) for phase, colors in groups.items()}
            return [[phase_color[(r + c) % period] for c in range(w)] for r in range(h)]
    return [row[:] for row in grid]
